// Rewrite absolute path keys in coverage-final.json from the source tree to the
// instrumented tree so crap4js can match coverage to scanned files.
const fs = require('fs');
const cov = JSON.parse(fs.readFileSync('/tmp/cov/coverage-final.json', 'utf8'));
const SRC = '/home/runner/work/dmtools-agents/dmtools-agents/';
const DST = '/tmp/inst/';
const out = {};
for (const [k, v] of Object.entries(cov)) {
    const nk = k.startsWith(SRC) ? DST + k.slice(SRC.length) : k;
    if (v && v.path && v.path.startsWith && v.path.startsWith(SRC)) {
        v.path = DST + v.path.slice(SRC.length);
    }
    out[nk] = v;
}
fs.writeFileSync('/tmp/cov/coverage-final.json', JSON.stringify(out));
console.log('rewritten:', Object.keys(out).length, 'entries');

