cd /home/runner/work/dmtools-agents/dmtools-agents && node << 'EOF'
const fs = require('fs');
function parse(file) {
    const rows = fs.readFileSync(file, 'utf8').split('\n').map(l => l.trim().split(/\s+/))
        .filter(c => c.length >= 5 && /\.js$/.test(c[1]) && !isNaN(parseFloat(c[4])));
    const map = new Map();
    for (const c of rows) map.set(c[1] + '::' + c[0], { cc: +c[2], cov: c[3], crap: parseFloat(c[4]) });
    return map;
}
const before = parse('/tmp/crap_before_aligned.txt');
const after = parse('/tmp/crap_final.txt');
const files = ['js/preCliDevelopmentSetup.js','js/triggerStoryTestAutomation.js','js/recoverMergedPRTicket.js','js/recoverStuckDevelopment.js','js/preCliKnowledgeUpdateSetup.js','js/storyTestAutomationRework.js','js/moveToInTesting.js','js/developTicketAndCreatePR.js','js/mergeStoryTestAutomationPR.js','js/triggerBugTestAutomation.js','js/finishTestCasesGeneration.js','js/timerAutoCommitAndSave.js'];
let grew = [], newOver8 = [], improved = 0;
for (const [key, b] of before) {
    if (!files.includes(key.split('::')[0])) continue;
    const a = after.get(key);
    if (!a) continue; // function removed by the split
    if (a.crap > b.crap + 0.05) grew.push(key + ' ' + b.crap + '->' + a.crap);
    if (a.crap < b.crap - 0.05) improved++;
}
for (const [key, a] of after) {
    if (!files.includes(key.split('::')[0])) continue;
    if (!before.has(key) && a.crap > 8.0) newOver8.push(key + ' ' + a.crap);
}
console.log('grew:', grew.length ? grew : 'none');
console.log('new helpers over 8.0:', newOver8.length ? newOver8 : 'none');
console.log('functions improved:', improved);
// all listed targets after:
const targets = ['js/preCliDevelopmentSetup.js::reportExistingDevBranch','js/triggerStoryTestAutomation.js::action','js/recoverMergedPRTicket.js::findMergedPRForTicket','js/recoverStuckDevelopment.js::action','js/preCliKnowledgeUpdateSetup.js::resolvePrContext','js/storyTestAutomationRework.js::commitAndPush','js/moveToInTesting.js::action','js/developTicketAndCreatePR.js::branchCarriesWork','js/mergeStoryTestAutomationPR.js::findPRForStory','js/triggerBugTestAutomation.js::action','js/finishTestCasesGeneration.js::action','js/timerAutoCommitAndSave.js::saveSessionArtefact'];
let worst = 0;
for (const t of targets) { const a = after.get(t); if (!a) { console.log('MISSING', t); continue; } worst = Math.max(worst, a.crap); }
console.log('worst target CRAP after:', worst);
EOF

